+  return false; // so far Android and IOS are only 32-bit
+#elif defined(TARGET_POSIX)
+  struct utsname un;
+  if (uname(&un) == 0)
+  {
+    std::string machine(un.machine);
+    if (machine == "x86_64" || machine == "amd64" || machine == "ppc64" || machine == "ia64")
+      return true;
+    return false;
+  }
+  return false; // can't detect
+#else
   return false;
-#endif // TARGET_WINDOWS
+#endif
+}
+
+bool CSysInfo::IsXBMC64bit(void)

body:
@t-nelson  return 'int' is good solution. Can distinguish between failed and '32' bit. And easily extendible in future for 128-bit :)
I don't see any issue. If someone need to distinguish between 32 and 64 bit then ifdefs can be used.
If someone would like to use this function instead of ifdefs - I see no problem. Compiler will optimize call and even cut not needed code for selected bitness.

